def longestDiverseString(a: int, b: int, c: int) -> str:
    def build(s, chars):
        if not chars:
            return s
        if len(s) < 2 or not (s[-1] == s[-2] == chars[0][0]):
            char, count = chars.pop(0)
            s += char
            if count > 1:
                chars.insert(0, (char, count - 1))
            chars.sort(key=lambda x: -x[1])
            return build(s, chars)
        else:
            if len(chars) == 1:
                return s
            char, count = chars.pop(1)
            s += char
            if count > 1:
                chars.append((char, count - 1))
            chars.sort(key=lambda x: - x[1])
            return build(s, chars)

    return build('', [('a', a), ('b', b), ('c', c)])
